// Package prng gives the seed generator its randomness: deterministic,
// splittable streams derived from one user-supplied seed.
//
// # Design
//
// Every random decision in the generator draws from a stream named by a label
// and an index, for example ("note.content", 4711). A stream's state is
// derived from (seed, label, index) alone, never from how many numbers some
// other stream has consumed. That is what makes the output byte-identical
// whatever order the work is done in: notes can be generated by parallel
// workers, and adding a new kind of decision does not shift the numbers every
// existing decision sees.
//
// Streams are PCG (math/rand/v2), seeded through SplitMix64 so that nearby
// seeds and indexes give unrelated streams.
//
// # Invariants
//
//   - For fixed (seed, label, index) the sequence of values is fixed for a
//     given version of this package. Changing any helper below changes the
//     generated data, so it bumps the generator version.
//   - No helper iterates a Go map.
//
// # Porting notes
//
// Seeds are not portable across languages (Go PCG and rand_pcg differ in
// output mapping). The seed data itself, not the seed, is what other
// languages share.
package prng

import (
	"hash/fnv"
	"math"
	"math/rand/v2"
)

// Source creates named streams from one root seed.
type Source struct {
	seed uint64
}

// New returns a Source for the given root seed.
func New(seed uint64) Source { return Source{seed: seed} }

// Seed returns the root seed.
func (s Source) Seed() uint64 { return s.seed }

// Stream returns the stream named (label, index). Calling it twice with the
// same arguments returns two streams that produce the same values.
func (s Source) Stream(label string, index uint64) *Rand {
	h := fnv.New64a()
	_, _ = h.Write([]byte(label))
	a := splitMix(s.seed ^ splitMix(h.Sum64()) ^ splitMix(index+0x632BE59BD9B4E019))
	b := splitMix(a ^ 0x9E3779B97F4A7C15)
	return &Rand{r: rand.New(rand.NewPCG(a, b))}
}

// splitMix is one round of SplitMix64, a good integer mixer.
func splitMix(x uint64) uint64 {
	x += 0x9E3779B97F4A7C15
	x = (x ^ (x >> 30)) * 0xBF58476D1CE4E5B9
	x = (x ^ (x >> 27)) * 0x94D049BB133111EB
	return x ^ (x >> 31)
}

// Rand is one deterministic stream with the helpers the generator needs.
type Rand struct {
	r *rand.Rand
}

// Uint64 returns a uniformly random 64-bit value.
func (r *Rand) Uint64() uint64 { return r.r.Uint64() }

// IntN returns a value in [0, n). n must be positive.
func (r *Rand) IntN(n int) int { return r.r.IntN(n) }

// Range returns a value in [lo, hi], inclusive at both ends.
func (r *Rand) Range(lo, hi int) int {
	if hi <= lo {
		return lo
	}
	return lo + r.r.IntN(hi-lo+1)
}

// Float64 returns a value in [0, 1).
func (r *Rand) Float64() float64 { return r.r.Float64() }

// Chance returns true with probability p.
func (r *Rand) Chance(p float64) bool { return r.r.Float64() < p }

// Pick returns a uniformly chosen element of items, which must not be empty.
func Pick[T any](r *Rand, items []T) T { return items[r.r.IntN(len(items))] }

// Shuffle permutes items in place.
func Shuffle[T any](r *Rand, items []T) {
	r.r.Shuffle(len(items), func(i, j int) { items[i], items[j] = items[j], items[i] })
}

// Sample returns k distinct indexes from [0, n), in the order drawn. k is
// clamped to n.
func (r *Rand) Sample(n, k int) []int {
	if k > n {
		k = n
	}
	// Partial Fisher-Yates over an index slice: exact and O(n) memory, which
	// is fine for the sizes the generator uses (at most a few hundred
	// thousand).
	idx := make([]int, n)
	for i := range idx {
		idx[i] = i
	}
	for i := 0; i < k; i++ {
		j := i + r.r.IntN(n-i)
		idx[i], idx[j] = idx[j], idx[i]
	}
	return idx[:k]
}

// Zipf draws ranks in [0, n) with probability proportional to 1/(rank+1)^s.
// The generator uses it for tag popularity and out-degree, so a few values are
// very common and most are rare.
type Zipf struct {
	cdf []float64
}

// NewZipf precomputes the cumulative distribution for n ranks with exponent
// s.
func NewZipf(n int, s float64) *Zipf {
	cdf := make([]float64, n)
	total := 0.0
	for i := 0; i < n; i++ {
		total += 1 / math.Pow(float64(i+1), s)
		cdf[i] = total
	}
	for i := range cdf {
		cdf[i] /= total
	}
	return &Zipf{cdf: cdf}
}

// Draw returns one rank.
func (z *Zipf) Draw(r *Rand) int {
	u := r.Float64()
	lo, hi := 0, len(z.cdf)-1
	for lo < hi {
		mid := (lo + hi) / 2
		if z.cdf[mid] < u {
			lo = mid + 1
		} else {
			hi = mid
		}
	}
	return lo
}
